BEGIN;
CREATE TABLE knowledge_chunk(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,chunk_id text NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,ordinal integer NOT NULL CHECK(ordinal BETWEEN 0 AND 199),start_offset integer NOT NULL CHECK(start_offset>=0),end_offset integer NOT NULL CHECK(end_offset>start_offset),checksum text NOT NULL CHECK(checksum~'^sha256:[a-f0-9]{64}$'),classification text NOT NULL,policy_version text NOT NULL,chunking_version text NOT NULL,PRIMARY KEY(tenant_id,workspace_id,chunk_id));
CREATE TABLE knowledge_embedding(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,embedding_id text NOT NULL,chunk_id text NOT NULL,model_profile text NOT NULL,model_version text NOT NULL,dimensions integer NOT NULL CHECK(dimensions BETWEEN 1 AND 4096),vector_checksum text NOT NULL CHECK(vector_checksum~'^sha256:[a-f0-9]{64}$'),index_version text NOT NULL,status text NOT NULL CHECK(status IN('READY','REMOVED')),PRIMARY KEY(tenant_id,workspace_id,embedding_id),FOREIGN KEY(tenant_id,workspace_id,chunk_id) REFERENCES knowledge_chunk(tenant_id,workspace_id,chunk_id) ON DELETE RESTRICT);
REVOKE ALL ON knowledge_chunk,knowledge_embedding FROM PUBLIC; GRANT SELECT,INSERT,UPDATE(status) ON knowledge_chunk,knowledge_embedding TO domus_knowledge_runtime;
ALTER TABLE knowledge_chunk ENABLE ROW LEVEL SECURITY; ALTER TABLE knowledge_chunk FORCE ROW LEVEL SECURITY; ALTER TABLE knowledge_embedding ENABLE ROW LEVEL SECURITY; ALTER TABLE knowledge_embedding FORCE ROW LEVEL SECURITY;
CREATE POLICY chunk_scope ON knowledge_chunk TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id') AND workspace_id=domus_security.current_uuid('app.current_workspace_id')) WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id') AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
CREATE POLICY embedding_scope ON knowledge_embedding TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id') AND workspace_id=domus_security.current_uuid('app.current_workspace_id')) WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id') AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description) VALUES(20,'V1-410 versioned chunks and embeddings') ON CONFLICT(version) DO NOTHING; COMMIT;
